<?php
require __DIR__.'/app/bootstrap.php';
$userId=require_auth();$pdo=db();$galleryService=new VacationPhotoGalleryService($pdo,__DIR__);$error=null;$success=flash('success');
if($_SERVER['REQUEST_METHOD']==='POST'){
    verify_csrf();
    try{
        $action=(string)($_POST['action']??'');$id=(int)($_POST['generation_id']??0);
        if($action==='favorite'){$on=$galleryService->toggleFavorite($userId,$id);flash('success',$on?'Added to favorites.':'Removed from favorites.');}
        elseif($action==='archive'){$galleryService->setArchived($userId,$id,true);flash('success','Vacation photo archived.');}
        elseif($action==='restore'){$galleryService->setArchived($userId,$id,false);flash('success','Vacation photo restored.');}
        elseif($action==='delete'){$galleryService->delete($userId,$id);flash('success','Vacation photo deleted.');}
        elseif($action==='share'){
            $token=$galleryService->enableShare($userId,$id);
            $_SESSION['vacation_share_token']=$token;
            flash('success','Share link created. Choose how ridiculous you want the presentation to be.');
        }
        elseif($action==='unshare'){$galleryService->disableShare($userId,$id);flash('success','Public share link disabled.');}
        elseif($action==='dream_cover'){$galleryService->setDreamCover($userId,$id,(int)($_POST['dream_trip_id']??0));flash('success','Dream Trip cover updated.');}
        elseif($action==='regenerate'){
            $created=$galleryService->regenerate($userId,$id,[
                'scene'=>trim((string)($_POST['scene']??'')),
                'vibe'=>(string)($_POST['vibe']??'realistic'),
                'over_the_top_strength'=>max(0,min(100,(int)($_POST['over_the_top_strength']??35))),
            ]);
            flash('success','Remix generated. Vacation Brain has made the situation worse in a productive way.');
        }
        $query=[];if(!empty($_GET['favorites']))$query['favorites']=1;if(!empty($_GET['archived']))$query['archived']=1;if(!empty($_GET['destination_id']))$query['destination_id']=(int)$_GET['destination_id'];
        redirect('vacation-gallery.php'.($query?'?'.http_build_query($query):''));
    }catch(Throwable $e){$error=$e->getMessage();}
}
$filters=['favorites'=>!empty($_GET['favorites']),'archived'=>!empty($_GET['archived']),'destination_id'=>(int)($_GET['destination_id']??0)];
$items=$galleryService->gallery($userId,$filters);$destinations=$galleryService->destinations($userId);
$dreamStmt=$pdo->prepare('SELECT id,name FROM dream_trips WHERE user_id=? AND status<>"abandoned" ORDER BY updated_at DESC,id DESC LIMIT 30');$dreamStmt->execute([$userId]);$dreams=$dreamStmt->fetchAll()?:[];
$shareToken=$_SESSION['vacation_share_token']??null;unset($_SESSION['vacation_share_token']);$success=flash('success')??$success;
$groups=[];foreach($items as $item){$key=(string)((int)($item['destination_catalog_id']??0)).'|'.(string)$item['destination'];$groups[$key]['name']=$item['catalog_destination_name']?:$item['destination'];$groups[$key]['destination_id']=(int)($item['destination_catalog_id']??0);$groups[$key]['items'][]=$item;}
$title='My Fake Vacations';require __DIR__.'/partials/header.php';
?>
