<details class="vg-remix"><summary>Remix this vacation</summary><form method="post" class="vg-remix-form"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="regenerate"><input type="hidden" name="generation_id" value="<?=(int)$item['id']?>"><label>Scene<input class="input" name="scene" maxlength="500" value="<?=e((string)($item['scene']??''))?>" placeholder="Make the evidence more suspicious..."></label><div class="vg-remix-row"><label>Vibe<select class="input" name="vibe"><?php foreach(['realistic'=>'Realistic','luxury'=>'Luxury','adventure'=>'Adventure','relaxed'=>'Relaxed','touristy'=>'Touristy','funny'=>'Funny'] as $value=>$label):?><option value="<?=$value?>" <?=($item['vibe']??'realistic')===$value?'selected':''?>><?=$label?></option><?php endforeach;?></select></label><label><span class="vg-remix-strength-head"><span>Over the Top</span><output data-remix-output><?=(int)$item['over_the_top_strength']?></output></span><input data-remix-strength type="range" name="over_the_top_strength" min="0" max="100" step="1" value="<?=(int)$item['over_the_top_strength']?>"></label></div><button class="vg-remix-submit" type="submit">Generate remix</button></form></details>
<div class="vg-actions"><?php if(empty($item['share_enabled'])):?><form method="post"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="share"><input type="hidden" name="generation_id" value="<?=(int)$item['id']?>"><button type="submit">Make shareable</button></form><?php else:?><a href="<?=e(app_url('vacation-photo-share.php?token='.$item['share_token'].'&style=diagnosis'))?>" target="_blank">Open share</a><form method="post"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="unshare"><input type="hidden" name="generation_id" value="<?=(int)$item['id']?>"><button type="submit">Unshare</button></form><?php endif;?><?php if(!$filters['archived']):?><form method="post"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="archive"><input type="hidden" name="generation_id" value="<?=(int)$item['id']?>"><button type="submit">Archive</button></form><?php else:?><form method="post"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="restore"><input type="hidden" name="generation_id" value="<?=(int)$item['id']?>"><button type="submit">Restore</button></form><?php endif;?><form method="post" onsubmit="return confirm('Permanently delete this generated image?')"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="generation_id" value="<?=(int)$item['id']?>"><button class="danger" type="submit">Delete</button></form></div>
