<?php if($dreams):?><form method="post" class="vg-dream"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="dream_cover"><input type="hidden" name="generation_id" value="<?=(int)$item['id']?>"><select class="input" name="dream_trip_id" required><option value="">Use as Dream Trip cover…</option><?php foreach($dreams as $dream):?><option value="<?=(int)$dream['id']?>" <?=((int)($item['dream_trip_id']??0)===(int)$dream['id'])?'selected':''?>><?=e($dream['name'])?></option><?php endforeach;?></select><button class="button secondary small" type="submit">Set</button></form><?php endif;?></div></article><?php endforeach;?>
